package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if !scanner.Scan() {
		return
	}
	m, _ := strconv.Atoi(scanner.Text())
	n := 1
	for i := 1; i <= m; i++ {
		n += 4 * (i - 1)
	}
	fmt.Println(n)
}

